TARGETS=[(re.compile(r,re.I),t) for r,t in TARGETS]
ASSETS=[(re.compile(r,re.I),t) for r,t in ASSETS]
def tag(text,ivnames):
    out=[]
    for rx,t in TARGETS:
        if rx.search(text) and t not in out: out.append(t)
    note=""
    for rx,t in ASSETS:
        if rx.search(ivnames) or rx.search(text[:300]): note=t; break
    return out[:6],note
